-- AnyVendor provisioning, 3 Nov 2026. Idempotent. Run as a direct database session AFTER tenancy_hardening.
-- Creates three business workspaces, gives the verified user jake@thebarpeople.co.uk (f91e23fc-3aa3-4fcb-a3cc-e2b1f59d14f1)
-- staff + owner of The Bar People, labelled internal test plans, the starter manifest, and a seeded v1 revision
-- where nothing is published. Sends no email. Creates no auth users.
do $body$
declare v_id uuid; v_rev uuid; v_jake uuid := 'f91e23fc-3aa3-4fcb-a3cc-e2b1f59d14f1';
begin
  if not exists (select 1 from auth.users where id = v_jake and lower(email) = 'jake@thebarpeople.co.uk' and email_confirmed_at is not null) then
    raise exception 'verified Jake user not found; stop';
  end if;

  -- The Bar People
  v_id := public.provision_business('The Bar People', 'the-bar-people', 'the-bar-people', 'bespoke');
  perform public.grant_internal_plan(v_id, 'social', 'Internal test plan (AnyVendor QA, not a paid subscription)', now() + interval '60 days');
  if (select manifest_version from public.websites where business_id = v_id) = 0 then
    perform public.set_site_manifest(v_id, '{"version":1,"name":"Starter (replace with the site''s own manifest)","sections":[{"key":"hero","label":"Hero","fields":[{"key":"headline","type":"text","max":120},{"key":"subheadline","type":"textarea","max":300},{"key":"image","type":"image"},{"key":"cta","type":"link"}]},{"key":"about","label":"About","fields":[{"key":"title","type":"text","max":120},{"key":"text","type":"richtext","max":4000}]},{"key":"services","label":"Services","fields":[{"key":"items","type":"list","max":12,"fields":[{"key":"title","type":"text","max":80},{"key":"text","type":"textarea","max":400},{"key":"image","type":"image"}]}]},{"key":"gallery","label":"Gallery","fields":[{"key":"images","type":"list","max":30,"fields":[{"key":"image","type":"image"}]}]},{"key":"testimonials","label":"Testimonials","fields":[{"key":"items","type":"list","max":12,"fields":[{"key":"quote","type":"textarea","max":600},{"key":"name","type":"text","max":80}]}]},{"key":"contact","label":"Contact","fields":[{"key":"email","type":"text","max":200},{"key":"phone","type":"text","max":40},{"key":"area","type":"text","max":160},{"key":"booking","type":"link"}]},{"key":"seo","label":"Search","fields":[{"key":"title","type":"text","max":70},{"key":"description","type":"textarea","max":160}]}]}'::jsonb);
  end if;
  if (select published_revision_id from public.websites where business_id = v_id) is null then
    update public.websites set draft = '{"hero":{"headline":"The Bar People","subheadline":"You bring the guests, we’ll bring the rest!","image":{"src":"","alt":""},"cta":{"href":"https://thebarpeople.co.uk/","label":"Visit thebarpeople.co.uk"}},"about":{"title":"About The Bar People","text":"Their bespoke pop-up bars are modular and can be customised for indoor or outdoor use, in any size or colour, with listed sizes running from 5ft up to a 40ft island. For corporate events they describe more than a decade of experience, offering signature cocktails, branded bar setups and interactive cocktail stations, plus eco-friendly options such as biodegradable straws and locally sourced ingredients. They handle everything from setup to cleanup.\n\nFor weddings, they provide bar service for a few hours or the whole day, with custom cocktail menus, themed setups, and wine and beer stations. Non-alcoholic drinks and mocktails can be added to any package, and all-inclusive packages include setup and takedown. Their cash bars are described as licensed to serve alcohol at any venue.\n\nThe business is run by The Bar People Limited (company number 12161824). Event management is handled as a team: Jake Lee looks after corporate events and logistics, and Kim Knight looks after private events and weddings. They recommend booking at least three months ahead, particularly for peak dates, and say they also cater for last-minute events. The ''We''ve Supported'' section of their homepage shows brand logos including Salesforce, Sky, O2, EE and Batiste."},"services":{"items":[{"title":"All-Inclusive Bar Hire","text":"A single per-person price covers drinks, staff, the bar, glassware, ice and setup, with unlimited drinks during the event. Packages depend on availability, date, location and requirements.","image":{"src":"","alt":""}},{"title":"Dry Hire","text":"Clients supply the drinks; The Bar People provides the mobile bar, bar staff, glassware and ice. Dry hire is available for both indoor and outdoor events.","image":{"src":"","alt":""}},{"title":"Cash Bar Hire","text":"Guests pay for their own drinks. They handle licensing, staff, equipment and a customisable menu, take cash and card, and can offer pre-purchased drink tickets. A setup fee applies, usually with a minimum sales requirement.","image":{"src":"","alt":""}},{"title":"Pop-Up and Branded Bars","text":"Modular bars customised for indoor or outdoor use in any size or colour, from 5ft to a 40ft island. Corporate options include branded bar setups, signature cocktails, interactive cocktail stations and professional mixologists.","image":{"src":"","alt":""}},{"title":"Event Management","text":"Full event planning from start to finish, covering venue selection and coordination, vendor management for catering and entertainment, timeline management and on-site coordination on the day. Costs are itemised in proposals.","image":{"src":"","alt":""}},{"title":"Staff and Glass Hire","text":"Staff hire is listed among their core services. Glass hire covers polished, wrapped glasses delivered to the venue and collected afterwards, and the glasses can be returned dirty.","image":{"src":"","alt":""}}]},"gallery":{"images":[]},"testimonials":{"items":[]},"contact":{"email":"","phone":"","area":"","booking":{"href":"https://thebarpeople.co.uk/","label":"Enquire"}},"seo":{"title":"The Bar People | Mobile bar hire","description":"You bring the guests, we’ll bring the rest!"}}'::jsonb, draft_version = 1, updated_at = now() where business_id = v_id and draft_version = 0;
    insert into public.website_revisions (business_id, version, action, content, created_by) values (v_id, 1, 'publish', '{"hero":{"headline":"The Bar People","subheadline":"You bring the guests, we’ll bring the rest!","image":{"src":"","alt":""},"cta":{"href":"https://thebarpeople.co.uk/","label":"Visit thebarpeople.co.uk"}},"about":{"title":"About The Bar People","text":"Their bespoke pop-up bars are modular and can be customised for indoor or outdoor use, in any size or colour, with listed sizes running from 5ft up to a 40ft island. For corporate events they describe more than a decade of experience, offering signature cocktails, branded bar setups and interactive cocktail stations, plus eco-friendly options such as biodegradable straws and locally sourced ingredients. They handle everything from setup to cleanup.\n\nFor weddings, they provide bar service for a few hours or the whole day, with custom cocktail menus, themed setups, and wine and beer stations. Non-alcoholic drinks and mocktails can be added to any package, and all-inclusive packages include setup and takedown. Their cash bars are described as licensed to serve alcohol at any venue.\n\nThe business is run by The Bar People Limited (company number 12161824). Event management is handled as a team: Jake Lee looks after corporate events and logistics, and Kim Knight looks after private events and weddings. They recommend booking at least three months ahead, particularly for peak dates, and say they also cater for last-minute events. The ''We''ve Supported'' section of their homepage shows brand logos including Salesforce, Sky, O2, EE and Batiste."},"services":{"items":[{"title":"All-Inclusive Bar Hire","text":"A single per-person price covers drinks, staff, the bar, glassware, ice and setup, with unlimited drinks during the event. Packages depend on availability, date, location and requirements.","image":{"src":"","alt":""}},{"title":"Dry Hire","text":"Clients supply the drinks; The Bar People provides the mobile bar, bar staff, glassware and ice. Dry hire is available for both indoor and outdoor events.","image":{"src":"","alt":""}},{"title":"Cash Bar Hire","text":"Guests pay for their own drinks. They handle licensing, staff, equipment and a customisable menu, take cash and card, and can offer pre-purchased drink tickets. A setup fee applies, usually with a minimum sales requirement.","image":{"src":"","alt":""}},{"title":"Pop-Up and Branded Bars","text":"Modular bars customised for indoor or outdoor use in any size or colour, from 5ft to a 40ft island. Corporate options include branded bar setups, signature cocktails, interactive cocktail stations and professional mixologists.","image":{"src":"","alt":""}},{"title":"Event Management","text":"Full event planning from start to finish, covering venue selection and coordination, vendor management for catering and entertainment, timeline management and on-site coordination on the day. Costs are itemised in proposals.","image":{"src":"","alt":""}},{"title":"Staff and Glass Hire","text":"Staff hire is listed among their core services. Glass hire covers polished, wrapped glasses delivered to the venue and collected afterwards, and the glasses can be returned dirty.","image":{"src":"","alt":""}}]},"gallery":{"images":[]},"testimonials":{"items":[]},"contact":{"email":"","phone":"","area":"","booking":{"href":"https://thebarpeople.co.uk/","label":"Enquire"}},"seo":{"title":"The Bar People | Mobile bar hire","description":"You bring the guests, we’ll bring the rest!"}}'::jsonb, null) returning id into v_rev;
    update public.websites set published_revision_id = v_rev, published_at = now() where business_id = v_id;
    insert into public.audit_log (actor, business_id, action, detail) values (null, v_id, 'site.seeded', jsonb_build_object('revision', v_rev));
  end if;

  -- Jake: AnyVendor staff (super-admin) and owner of The Bar People. Applied only because his email is verified.
  insert into public.pending_access (email, business_id, role, make_staff, note)
    select 'jake@thebarpeople.co.uk', null, 'owner', true, 'AnyVendor super-admin (Jake Lee)'
    where not exists (select 1 from public.pending_access where email = 'jake@thebarpeople.co.uk' and business_id is null)
      and not exists (select 1 from public.staff_members where user_id = v_jake);
  insert into public.pending_access (email, business_id, role, make_staff, note)
    select 'jake@thebarpeople.co.uk', v_id, 'owner', false, 'The Bar People owner'
    where not exists (select 1 from public.pending_access where email = 'jake@thebarpeople.co.uk' and business_id = v_id)
      and not exists (select 1 from public.memberships where user_id = v_jake and business_id = v_id);
  perform public.apply_pending_access(v_jake);

  -- Floriography Studio
  v_id := public.provision_business('Floriography Studio', 'floriography-studio', null, 'bespoke');
  perform public.grant_internal_plan(v_id, 'social', 'Internal test plan (AnyVendor QA, not a paid subscription)', now() + interval '60 days');
  if (select manifest_version from public.websites where business_id = v_id) = 0 then
    perform public.set_site_manifest(v_id, '{"version":1,"name":"Starter (replace with the site''s own manifest)","sections":[{"key":"hero","label":"Hero","fields":[{"key":"headline","type":"text","max":120},{"key":"subheadline","type":"textarea","max":300},{"key":"image","type":"image"},{"key":"cta","type":"link"}]},{"key":"about","label":"About","fields":[{"key":"title","type":"text","max":120},{"key":"text","type":"richtext","max":4000}]},{"key":"services","label":"Services","fields":[{"key":"items","type":"list","max":12,"fields":[{"key":"title","type":"text","max":80},{"key":"text","type":"textarea","max":400},{"key":"image","type":"image"}]}]},{"key":"gallery","label":"Gallery","fields":[{"key":"images","type":"list","max":30,"fields":[{"key":"image","type":"image"}]}]},{"key":"testimonials","label":"Testimonials","fields":[{"key":"items","type":"list","max":12,"fields":[{"key":"quote","type":"textarea","max":600},{"key":"name","type":"text","max":80}]}]},{"key":"contact","label":"Contact","fields":[{"key":"email","type":"text","max":200},{"key":"phone","type":"text","max":40},{"key":"area","type":"text","max":160},{"key":"booking","type":"link"}]},{"key":"seo","label":"Search","fields":[{"key":"title","type":"text","max":70},{"key":"description","type":"textarea","max":160}]}]}'::jsonb);
  end if;
  if (select published_revision_id from public.websites where business_id = v_id) is null then
    update public.websites set draft = '{"hero":{"headline":"Floriography Studio","subheadline":"","image":{"src":"","alt":""},"cta":{"href":"","label":""}},"about":{"title":"","text":""},"services":{"items":[]},"gallery":{"images":[]},"testimonials":{"items":[]},"contact":{"email":"","phone":"","area":"","booking":{"href":"","label":""}},"seo":{"title":"","description":""}}'::jsonb, draft_version = 1, updated_at = now() where business_id = v_id and draft_version = 0;
    insert into public.website_revisions (business_id, version, action, content, created_by) values (v_id, 1, 'publish', '{"hero":{"headline":"Floriography Studio","subheadline":"","image":{"src":"","alt":""},"cta":{"href":"","label":""}},"about":{"title":"","text":""},"services":{"items":[]},"gallery":{"images":[]},"testimonials":{"items":[]},"contact":{"email":"","phone":"","area":"","booking":{"href":"","label":""}},"seo":{"title":"","description":""}}'::jsonb, null) returning id into v_rev;
    update public.websites set published_revision_id = v_rev, published_at = now() where business_id = v_id;
    insert into public.audit_log (actor, business_id, action, detail) values (null, v_id, 'site.seeded', jsonb_build_object('revision', v_rev));
  end if;

  -- Mr Tee's Mobile Crazy Golf
  v_id := public.provision_business('Mr Tee''s Mobile Crazy Golf', 'mr-tees-crazy-golf', null, 'bespoke');
  perform public.grant_internal_plan(v_id, 'social', 'Internal test plan (AnyVendor QA, not a paid subscription)', now() + interval '60 days');
  if (select manifest_version from public.websites where business_id = v_id) = 0 then
    perform public.set_site_manifest(v_id, '{"version":1,"name":"Starter (replace with the site''s own manifest)","sections":[{"key":"hero","label":"Hero","fields":[{"key":"headline","type":"text","max":120},{"key":"subheadline","type":"textarea","max":300},{"key":"image","type":"image"},{"key":"cta","type":"link"}]},{"key":"about","label":"About","fields":[{"key":"title","type":"text","max":120},{"key":"text","type":"richtext","max":4000}]},{"key":"services","label":"Services","fields":[{"key":"items","type":"list","max":12,"fields":[{"key":"title","type":"text","max":80},{"key":"text","type":"textarea","max":400},{"key":"image","type":"image"}]}]},{"key":"gallery","label":"Gallery","fields":[{"key":"images","type":"list","max":30,"fields":[{"key":"image","type":"image"}]}]},{"key":"testimonials","label":"Testimonials","fields":[{"key":"items","type":"list","max":12,"fields":[{"key":"quote","type":"textarea","max":600},{"key":"name","type":"text","max":80}]}]},{"key":"contact","label":"Contact","fields":[{"key":"email","type":"text","max":200},{"key":"phone","type":"text","max":40},{"key":"area","type":"text","max":160},{"key":"booking","type":"link"}]},{"key":"seo","label":"Search","fields":[{"key":"title","type":"text","max":70},{"key":"description","type":"textarea","max":160}]}]}'::jsonb);
  end if;
  if (select published_revision_id from public.websites where business_id = v_id) is null then
    update public.websites set draft = '{"hero":{"headline":"Mr Tee''s Mobile Crazy Golf","subheadline":"","image":{"src":"","alt":""},"cta":{"href":"","label":""}},"about":{"title":"","text":""},"services":{"items":[]},"gallery":{"images":[]},"testimonials":{"items":[]},"contact":{"email":"","phone":"","area":"","booking":{"href":"","label":""}},"seo":{"title":"","description":""}}'::jsonb, draft_version = 1, updated_at = now() where business_id = v_id and draft_version = 0;
    insert into public.website_revisions (business_id, version, action, content, created_by) values (v_id, 1, 'publish', '{"hero":{"headline":"Mr Tee''s Mobile Crazy Golf","subheadline":"","image":{"src":"","alt":""},"cta":{"href":"","label":""}},"about":{"title":"","text":""},"services":{"items":[]},"gallery":{"images":[]},"testimonials":{"items":[]},"contact":{"email":"","phone":"","area":"","booking":{"href":"","label":""}},"seo":{"title":"","description":""}}'::jsonb, null) returning id into v_rev;
    update public.websites set published_revision_id = v_rev, published_at = now() where business_id = v_id;
    insert into public.audit_log (actor, business_id, action, detail) values (null, v_id, 'site.seeded', jsonb_build_object('revision', v_rev));
  end if;
end $body$;

select b.slug, b.name, b.directory_slug, w.kind, w.manifest_version, w.published_revision_id is not null as published,
  (select plan::text || ' (' || label || ')' from public.internal_entitlements e where e.business_id = b.id) as internal_plan,
  (select count(*) from public.memberships m where m.business_id = b.id) as members
from public.businesses b join public.websites w on w.business_id = b.id order by b.slug;
select user_id, note from public.staff_members;
